// scripts/build-dem.mjs 로 생성한 파일 — 직접 고치지 마세요.
// 제주 고도(m) 격자. 범위 x -52~52km, z -26~26km (제주 중심 기준), 간격 0.25km, 행 우선(z 증가 = 남쪽).
// 출처: AWS Open Data Terrain Tiles (SRTM/NASADEM, GEBCO 등)
export const DEM = { x0: -52, z0: -26, step: 0.25, gx: 417, gz: 209 }
const B64 = ''
const bin = atob(B64)
const bytes = new Uint8Array(bin.length)
for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
export const DEM_M = new Int16Array(bytes.buffer)
